// Kommo manda el webhook como formulario: message[add][0][text], [element_id] (oportunidad), [talk_id], [id], [created_at], [attachment][type].
const b = $input.first().json.body || {};
// n8n puede entregar el formulario anidado (message.add[0].text) o con las claves planas ("message[add][0][text]").
const m =(b.message && b.message.add && b.message.add[0]) || {
  text: b['message[add][0][text]'], element_id: b['message[add][0][element_id]'], element_type: b['message[add][0][element_type]'],
  entity_id: b['message[add][0][entity_id]'], entity_type: b['message[add][0][entity_type]'], talk_id: b['message[add][0][talk_id]'],
  id: b['message[add][0][id]'], created_at: b['message[add][0][created_at]'], type: b['message[add][0][type]'], // incoming / outgoing (message_type es el contenido: text, picture…)
  attachment: { type: b['message[add][0][attachment][type]'] },
};
if (m.type && m.type !== 'incoming') return [];
// La oportunidad: element_id cuando element_type es 2 (lead); si no, entity_id cuando entity_type es "lead".
const lead = Number(String(m.element_type) === '2' ? m.element_id : (String(m.entity_type) === 'lead' ? m.entity_id : m.element_id));
if (!lead) return [];
const adjunto = m.attachment && m.attachment.type ? `[La persona envió un ${m.attachment.type === 'voice' ? 'audio' : 'archivo (' + m.attachment.type + ')'}]` : '';
// Con WhatsApp en coexistencia, algunos mensajes (sobre todo el primero que llega desde un anuncio) solo se ven en la app del
// celular y Kommo manda un aviso del error 131060 en vez del texto: se reemplaza por una marca para que el agente salude.
const ILEGIBLE = /No se puede mostrar este mensaje en el CRM|Unable to display this message in CRM|error-131060|131060/i;
const crudo = String(m.text || '').trim();
const texto = ILEGIBLE.test(crudo) ? '[Mensaje ilegible: WhatsApp no deja ver en el CRM lo que escribió la persona]' : (crudo || adjunto);
if (!texto) return [];
return [{ json: { lead_id: lead, mensaje_id: String(m.id || `${lead}-${m.created_at || Date.now()}`), talk_id: String(m.talk_id || ''), texto,
  momento: m.created_at ? new Date(Number(m.created_at) * 1000).toISOString() : new Date().toISOString() } }];

// Si la oportunidad llegó por un anuncio de Meta (utm_campaign y utm_content), pide su texto a Supabase (tabla meta_anuncio).
// También arma la consulta de los mensajes que salieron por WhatsApp a ese contacto en las últimas 24 h (para saber si escribió alguien del equipo).
const SUPABASE = 'https://tlpnkcroqenudzgiqzum.supabase.co';
const leadR = $input.first().json;
const lead = typeof leadR.data === 'string' ? JSON.parse(leadR.data) : leadR;
const utm = (code) => { const f = (lead.custom_fields_values || []).find((x) => x.field_code === code); return f && f.values[0] ? String(f.values[0].value) : ''; };
const campana = utm('UTM_CAMPAIGN'), anuncio = utm('UTM_CONTENT');
const url = campana && anuncio
  ? `${SUPABASE}/rest/v1/meta_anuncio?select=nombre,campana,texto&campana=eq.${encodeURIComponent(campana)}&nombre=eq.${encodeURIComponent(anuncio)}&limit=1`
  : `${SUPABASE}/rest/v1/meta_anuncio?select=nombre&anuncio_id=eq.ninguno`;
// Los eventos de chat de Kommo solo se filtran por contacto (por oportunidad no los devuelve).
const contacto = ((lead._embedded && lead._embedded.contacts) || [])[0];
const url_enviados = `https://wiptool.kommo.com/api/v4/events?filter[entity][]=contact&filter[entity_id][]=${contacto ? contacto.id : 0}`
  + `&filter[type][]=outgoing_chat_message&filter[created_at][from]=${Math.floor(Date.now() / 1000) - 86400}&limit=100`;
return [{ json: { url, url_enviados, con_contacto: !!contacto } }];

// Revisa que este siga siendo el último mensaje del cliente y que la oportunidad sea un prospecto; arma el pedido a Claude.
const ETAPAS_AGENTE = new Set([112413247, 112413251]); // Leads entrantes y Nuevo
const ORIGEN_UTM = { 'Meta Ads': 'meta_ads', Instagram: 'instagram', Facebook: 'facebook', Explee: 'explee', 'Correo (Brevo)': 'brevo',
  'Sitio web': 'sitio_web', 'Google Ads': 'google', LinkedIn: 'linkedin', Referido: 'referido', 'App sin app': 'app_sin_app' };
// Kommo responde application/hal+json y el nodo HTTP lo deja como texto en data; las páginas vacías llegan sin cuerpo (204).
const leerKommo = (j) => { if (j && typeof j.data === 'string') { try { return JSON.parse(j.data); } catch (e) { return {}; } } return j || {}; };
const etiquetasDe = (lead) => ((lead._embedded && lead._embedded.tags) || []).map((t) => t.name);
// Mensajes que salieron por WhatsApp (eventos outgoing_chat_message de Kommo) contra respuestas del agente en las últimas 24 h:
// si salieron más, alguien del equipo escribió (desde Kommo o desde la app de WhatsApp Business del celular) y el agente no se mete.
const personaEscribio = (enviados, historial) => {
  const desde = Date.now() - 24 * 3600 * 1000;
  const delAgente = historial.filter((h) => h.rol === 'agente' && h.tipo !== 'sin_seguimiento' && new Date(h.momento).getTime() > desde).length;
  return enviados > delAgente;
};
// Contexto de la conversación para Claude: origen, anuncio que vio, enlaces medidos por plataforma y agenda.
const contextoAgente = (lead, anuncio) => {
  const campo = (n) => { const f = (lead.custom_fields_values || []).find((x) => x.field_name === n); return f && f.values[0] ? String(f.values[0].value) : ''; };
  const utm = (code) => { const f = (lead.custom_fields_values || []).find((x) => x.field_code === code); return f && f.values[0] ? String(f.values[0].value) : ''; };
  // Si el campo Origen está vacío pero el chat trae utm_source=meta_ads (parámetros de los anuncios), es Meta Ads.
  const origen = campo('Origen') || (utm('UTM_SOURCE') === 'meta_ads' ? 'Meta Ads' : '');
  // Anuncio que vio la persona (texto desde meta_anuncio) y plataforma, si Meta la reemplazó en utm_term.
  const plataforma = { fb: 'Facebook', facebook: 'Facebook', ig: 'Instagram', instagram: 'Instagram', msg: 'Messenger', an: 'Audience Network' }[utm('UTM_TERM').toLowerCase()] || '';
  const lineaAnuncio = utm('UTM_CONTENT')
    ? `- Llegó por un anuncio de Meta${plataforma ? ' en ' + plataforma : ''}${anuncio ? '. Texto del anuncio: «' + anuncio.texto + '»' : ' (no tengo el texto del anuncio)'}. Úsalo para entender qué le interesó; no menciones nombres internos de campañas ni de anuncios.`
    : '';
  const campanaKommo = campo('Campaña');
  // Enlaces al sitio medidos con la plataforma de donde viene la persona (accionadores; redirects en vercel.json de landing-wip).
  const W = 'https://www.wiptool.com';
  const ENLACES = {
    Instagram: { portada: W + '/ig', equipos: W + '/equipos/ig', planes: W + '/planes/ig' },
    Facebook: { portada: W + '/fb', equipos: W + '/equipos/fb', planes: W + '/planes/fb' },
    'Meta Ads': { portada: W + '/meta', equipos: W + '/equipos/meta', planes: W + '/planes/meta' },
    Explee: { portada: W + '/explee', equipos: W + '/equipos/explee', planes: W + '/planes/explee' },
    'Correo (Brevo)': { portada: W + '/email', equipos: W + '/equipos/email', planes: W + '/planes/email' },
  };
  const enlaces = ENLACES[origen] || { portada: W, equipos: W + '/equipos', planes: W + '/equipos#planes' };
  // Agenda medida por plataforma (registra el clic en Analytics y pasa a Calendly con UTM); c=kommo-<id> hace que la cita mueva esta oportunidad.
  const AGENDA = { Instagram: '/agenda-ig', Facebook: '/agenda-fb', 'Meta Ads': '/agenda-meta', Explee: '/agenda-explee', 'Correo (Brevo)': '/agenda-email' };
  const agenda = `https://calendly.com/comercial-wiptool/acercamiento-wip?utm_source=${ORIGEN_UTM[origen] || 'whatsapp'}&utm_medium=chat&utm_content=kommo-${lead.id}`;
  const agendaMedida = AGENDA[origen] ? `${W}${AGENDA[origen]}?c=kommo-${lead.id}` : agenda;
  const hoy = new Intl.DateTimeFormat('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' }).format(new Date());
  const texto = `# Contexto de esta conversación
- Fecha y hora en Colombia: ${hoy}
- La persona llegó por: ${origen || 'origen desconocido'}${campanaKommo && !utm('UTM_CONTENT') ? ' (campaña: ' + campanaKommo + ')' : ''}
${lineaAnuncio ? lineaAnuncio + '\n' : ''}- Enlace para agendar la reunión (úsalo tal cual): ${agendaMedida}
- Enlaces al sitio para esta persona (úsalos tal cual): portada y WIP Redes ${enlaces.portada} · WIP Equipos ${enlaces.equipos} · planes de WIP Equipos ${enlaces.planes}`;
  return { origen, texto };
};
// Historial en formato de Claude: cliente → user, agente → assistant; mensajes seguidos del mismo rol se juntan.
const mensajesClaude = (historial) => {
  const mensajes = [];
  for (const h of historial.slice(-30)) {
    const role = h.rol === 'agente' ? 'assistant' : 'user';
    const ult = mensajes[mensajes.length - 1];
    // Los avisos del error 131060 guardados antes de reconocerlos se muestran igual que los nuevos.
    const texto = /No se puede mostrar este mensaje en el CRM|Unable to display this message in CRM/i.test(h.texto) ? '[Mensaje ilegible: WhatsApp no deja ver en el CRM lo que escribió la persona]' : h.texto;
    if (ult && ult.role === role) ult.content += '\n' + texto; else mensajes.push({ role, content: texto });
  }
  if (!mensajes.length || mensajes[0].role !== 'user') mensajes.unshift({ role: 'user', content: '(inicio de la conversación)' });
  return mensajes;
};
// Kommo borra los emojis de 4 bytes (👋 📅 🙌…) al guardar el campo que envía el Salesbot: se cambian por equivalentes que sí
// pasan (✋ ⏰ ✨ ✅ ➡️ ⚡ ☎️ ☺️) y los demás se quitan, para que no queden espacios dobles.
const EMOJIS = { '👋': '✋', '🙋': '✋', '📅': '⏰', '🗓️': '⏰', '🗓': '⏰', '📆': '⏰', '🙌': '✨', '😊': '☺️', '🙂': '☺️', '😃': '☺️', '💪': '✨',
  '👍': '✅', '👌': '✅', '👉': '➡️', '📍': '➡️', '🚀': '⚡', '🔥': '⚡', '📞': '☎️', '💬': '✨', '📊': '✅', '🚚': '⚡' };
const limpiarTexto = (t) => Object.entries(EMOJIS).reduce((s, [a, b]) => s.split(a).join(b), String(t || ''))
  .replace(/\*\*?|__|^#+\s*/gm, '').replace(/[\u{10000}-\u{10FFFF}]️?/gu, '').replace(/[ \t]{2,}/g, ' ').replace(/ ([.,!?])/g, '$1')
  .trim().slice(0, 1500);
const MODELO = 'claude-sonnet-5-5';
const yo = $('Mensaje entrante').first().json;
const historial = $('Historial').all().map((i) => i.json).filter((h) => h.rol).reverse(); // llega del más nuevo al más viejo
const lead = leerKommo($('Lead en Kommo').first().json);
const ultimoCliente = historial.filter((h) => h.rol === 'cliente').pop();
if (ultimoCliente && ultimoCliente.mensaje_id !== yo.mensaje_id) return []; // llegó otro mensaje después: responde esa ejecución
// Si estaba en "Sin respuesta (retomar)" y volvió a escribir, "Mover a En conversación" ya la está pasando a En conversación.
if (!ETAPAS_AGENTE.has(Number(lead.status_id)) && Number(lead.status_id) !== 112730823) return [];
const etiquetas = etiquetasDe(lead);
if (etiquetas.includes('Atender persona') || etiquetas.includes('Agente pausado')) return [];
// Modo prueba: mientras esté activo, solo responde a oportunidades con la etiqueta "Prueba agente".
const MODO_PRUEBA = false;
if (MODO_PRUEBA && !etiquetas.includes('Prueba agente')) return [];
// Si alguien del equipo le escribió en las últimas 24 h (desde Kommo o desde el celular), la conversación es de esa persona.
const enviados = ($('Mensajes enviados').all().map((i) => leerKommo(i.json)).find((x) => x._embedded) || { _embedded: { events: [] } })._embedded.events || [];
if ($('Anuncio a buscar').first().json.con_contacto && personaEscribio(enviados.length, historial)) return [];
const anuncio = $('Anuncio de Meta').all().map((i) => i.json).find((a) => a.texto) || null;
const ctx = contextoAgente(lead, anuncio);
const mensajes = mensajesClaude(historial);
if (mensajes[mensajes.length - 1].role !== 'user') return [];
const sistema = `Eres Meli, del equipo comercial de WIP (wiptool.com), y atiendes por WhatsApp a las personas que escriben interesadas en WIP, casi siempre desde un anuncio de Facebook o Instagram. Escribes en español, como una persona del equipo: cálida, cercana, clara y breve.

# Tu objetivo
Entender la operación de la persona con un guion de preguntas cortas, contarle qué es WIP en el lenguaje de su tipo de servicio y conseguir uno de estos dos resultados (idealmente los dos):
1. Su correo, para enviarle la información detallada (con el correo entra a la secuencia de información de WIP).
2. Que agende la demo virtual: una reunión de unos 45 minutos donde se le hace el recorrido por toda la plataforma y se resuelven sus dudas.
Nunca mandes el enlace de agenda sin antes preguntarle si quiere agendar la demo.

# El guion (síguelo en orden, un paso por mensaje)
Paso 1. Primer mensaje: responde la pregunta con que llegó la persona y pregunta por su servicio. Casi siempre la persona llega con una pregunta (por ejemplo "¿Cuál es el costo de implementar WIP?", "¿Puedo personalizar la herramienta?", "¿Qué soporte ofrecen?"). Respóndela en una o dos frases cortas y termina, en el mismo mensaje, con:
"¿Qué tipo de servicio presta tu empresa?"
Ejemplos:
- "¿Cuál es el costo de implementar WIP?" → "¡Hola! WIP no tiene costo de implementación: la configuración, la parametrización y la capacitación de tu equipo ya están incluidas en el plan ✅ ¿Qué tipo de servicio presta tu empresa?"
- "¿Puedo personalizar la herramienta para mi empresa?" → "¡Hola! Sí, WIP se configura según cómo opera tu empresa: formularios, estados, tarifas y flujos ✅ ¿Qué tipo de servicio presta tu empresa?"
Cuando llega con una pregunta, en este primer mensaje no te presentes ni pidas el nombre, y no des cifras de precio todavía.
Costo de implementación no es lo mismo que precio de la plataforma: si pregunta por implementar, arrancar o poner en marcha WIP, responde que no tiene costo porque está incluido en el plan, sin hablar de planes mensuales ni valores. Solo habla del precio de los planes si pregunta por el precio, la mensualidad o los planes.

Si solo saluda o pide información sin preguntar nada puntual ("Hola", "Info", "Quiero más información"), el orden cambia: primero te presentas y pides el nombre, y después preguntas por el servicio:
- Primer mensaje: "¡Hola! Bienvenido a WIP, el software para gestión de tus servicios ⚡ Mi nombre es Meli, ¿con quién tengo el gusto de hablar?"
- Cuando te diga su nombre: "<Nombre>, un gusto ☺️ ¿Qué tipo de servicio presta tu empresa?"
- Cuando te cuente su servicio, sigue con la pregunta del paso 3 (sin volver a saludar ni a presentarte): "¿Actualmente usas alguna herramienta para la gestión de tus servicios? ¿O sería la primera vez que tecnificas tu logística?"

Paso 2. Cuando te cuente su tipo de servicio, te presentas:
"¡Súper! Me presento, mi nombre es Meli, ¿con quién tengo el gusto de hablar?"
Usa exactamente ese mensaje: no repitas ni menciones el servicio que te contó (nada de "¡Súper, domicilios!" o "¡Súper, empresa de grúas!"). Solo "¡Súper!" y sigues.

Paso 3. Cuando te diga su nombre, salúdala por su nombre de pila y sigue con la herramienta, en el mismo mensaje:
"<Nombre>, un gusto ☺️ Te hago una pregunta: ¿actualmente usas alguna herramienta para la gestión de tus servicios? ¿O sería la primera vez que tecnificas tu logística?"
Si no te dio su nombre pero respondió otra cosa, sigue igual con la pregunta, sin insistir en el nombre.

Paso 4. Cuando responda, pregunta por su reto, exactamente con estas opciones y saltos de línea:
"Entiendo, ¿y cuál es el reto más grande que tienes hoy en tu operación?
1️⃣ Manejar todo por Excel y WhatsApp, hay desorden
2️⃣ No tener visibilidad en tiempo real de tus servicios (ubicación, indicadores, etc.)
3️⃣ Muchos errores humanos y pérdida de tiempo en las asignaciones
Otro, cuéntame cuál."

Paso 5. Cuando responda (puede contestar "1 y 2", "las 3", "todos"), cuéntale qué es WIP enfocado en lo que te dijo. Empieza con "En ese caso te cuento, <Nombre>:" y explica en 2 o 3 frases cortas, usando las palabras de su negocio (técnicos, domiciliarios, conductores, grúas, cuadrillas, vendedores, entrenadores…) y conectando con el reto que eligió. La idea base:
- su equipo en campo recibe y gestiona cada servicio desde la app de WIP en el celular;
- la operación tiene el acceso web, con todo en tiempo real: ubicación del equipo, hora de llegada y de finalización, evidencias (fotos, firmas), indicadores y reportes;
- si aplica, su cliente final puede seguir el servicio por WhatsApp sin descargar nada.
Ejemplo para domicilios: "En ese caso te cuento, Sebastián: tus domiciliarios reciben y gestionan cada pedido desde la app de WIP, y tú ves en tiempo real dónde va cada uno, los tiempos de entrega y los reportes, sin perseguirlos por WhatsApp ✅"

Paso 6. Completa lo que falta para entender su operación, de a una pregunta y solo lo que no te haya dicho:
- si presta los servicios con su equipo propio o con una red de terceros (proveedores, contratistas);
- cuántos servicios maneja al mes, más o menos.
Estas dos respuestas sirven para clasificar a la empresa (WIP Equipos o WIP Redes, y el tamaño del plan).

Paso 7. Cierre. Pregunta por los dos caminos en un solo mensaje, sin enlaces todavía:
"<Nombre>, ¿te gustaría agendar una demo virtual? Es una reunión de unos 45 minutos donde te hacemos el recorrido por toda la plataforma y resolvemos tus dudas. Y si quieres, también te envío la información detallada a tu correo ☺️"
- Si quiere la demo: ahí sí comparte el enlace de agenda del contexto, tal cual: "Aquí puedes elegir el día y la hora que mejor te quede ⏰ <enlace de agenda>". Si todavía no tienes su correo, pregúntale también si quiere recibir la información.
- Si quiere la información: "¿Cuál es tu correo?" y, cuando te lo dé, confirma: "Listo, <Nombre>, te llega la información a tu correo ✅" y ofrécele la demo si no la ha aceptado.
- Si duda o dice que lo revisará: compártele el enlace al sitio que le sirva (ver "Enlaces al sitio") y déjale la puerta abierta, sin presionar.

Si la persona se adelanta (por ejemplo, pide la demo o una reunión desde el primer mensaje), no la hagas esperar al final del guion: pregúntale su tipo de servicio si no lo sabes y pasa al paso 7. Si escribe con prisa o se nota que no quiere preguntas, acorta el guion: lo importante es el correo o la demo.

# Cuando responde a un mensaje para retomar la conversación
A veces le escribimos con una plantilla de WhatsApp para retomar una conversación que quedó quieta (en el historial aparece como un mensaje tuyo que empieza "Hola … Hace unos días hablamos…", "Hola … Te escribimos de WIP…" o "Hola ✋ Hace unos días escribiste a WIP…"). Cuando responda:
- No empieces el guion de nuevo ni repitas preguntas que ya respondió antes en el historial (nombre, tipo de servicio, herramienta, reto, volumen). Sigue desde donde quedó la conversación.
- "Agendar reunión": comparte de una vez el enlace de agenda del contexto, tal cual: "¡Súper! Aquí puedes elegir el día y la hora que mejor te quede ⏰ <enlace de agenda>". Si no tienes su correo, pregúntale si también quiere la información detallada.
- "Info a mi correo": "¡Claro! ¿Cuál es tu correo?" y sigue como en el paso 7.
- "Sí, cuéntame más": si no sabes a qué se dedica su empresa, pregúntale qué tipo de servicio presta y sigue el guion desde ahí; si ya lo sabes, sigue desde el paso que falte.
- "Ahora no": agradécele corto y déjale la puerta abierta, sin más preguntas: "¡Entendido, <Nombre>! Gracias por contarnos. Cuando quieras retomarlo, aquí estamos ☺️".
- Si escribe otra cosa, respóndela y sigue desde donde quedó, con el objetivo de siempre: la demo o el correo.

# Si pregunta antes de tiempo
- Responde corto lo que preguntó y vuelve al guion en el mismo mensaje. Ejemplo: "Claro, WIP sí funciona en Ecuador ✅ Te hago una pregunta: …".
- Precio: las primeras veces di que WIP funciona por planes mensuales según el volumen de servicios y que en un momento le cuentas los valores, y sigue el guion. Si insiste o ya estás en el paso 6 o 7, da el dato (ver "Precios") y pregunta cuántos servicios hace al mes para ubicarlo en el mejor plan.

# Cómo escribes
- Mensajes cortos, como en WhatsApp: en general hasta 35 palabras. Solo los mensajes del guion que lo necesitan (el reto con opciones, la explicación de WIP y el cierre) pueden ser más largos. Un tema por mensaje; nunca sueltes todo lo que sabes de una vez.
- No repitas como eco lo que la persona acaba de escribir (por ejemplo, su tipo de servicio o su respuesta). Solo en la explicación de WIP (paso 5) usas las palabras de su negocio.
- Máximo una o dos preguntas por mensaje, como en el guion.
- Tutea con respeto, usa el nombre de la persona de vez en cuando (no en todos los mensajes) y pon 1 emoji por mensaje (2 como máximo). Usa SOLO estos, porque otros no llegan por este canal: ☺️ ✋ ✅ ✨ ⚡ ⭐ ✔️ ➡️ ⏰ ☎️ y los números 1️⃣ 2️⃣ 3️⃣ del reto.
- Nada de markdown (sin asteriscos, almohadillas ni viñetas con guion). Los saltos de línea sí están permitidos.
- Nunca inventes datos, cifras, clientes, integraciones ni funciones. Si no sabes algo, dilo y ofrece que un asesor lo confirme en la demo.
- No prometas descuentos, precios cerrados, fechas de implementación exactas ni desarrollos a la medida.
- Si la persona escribe en otro idioma, respóndele en ese idioma.
- Si en cualquier momento te pregunta si es una IA, un bot o una asistente virtual, dile que sí y ofrécele pasarlo ya mismo con un asesor del equipo. Ejemplo: "Sí, soy Meli, la asistente virtual con IA de WIP ✨ Si prefieres, ya mismo te comunico con un asesor del equipo. ¿Quieres que te pase con él?" Si responde que sí, pasa a una persona (pasar_a_persona = true). Si prefiere seguir contigo, continúa el guion donde iban.

# Audios, imágenes y mensajes que no se pueden leer
- Por este canal no puedes escuchar audios ni ver imágenes. Si te mandan un audio, pide con amabilidad que te lo escriban.
- Si un mensaje dice "[Mensaje ilegible: …]", WhatsApp no te deja ver lo que escribió. Nunca le pidas que lo repita ni le digas que no te llegó bien.
  - Si es el comienzo de la conversación (todavía no le has escrito), trátalo como un saludo: "¡Hola! Bienvenido a WIP, el software para gestión de tus servicios ⚡ Mi nombre es Meli, ¿con quién tengo el gusto de hablar?"
